/**
 * The one correction the demo script hard-codes: protect safety and
 * verify before substituting. Folds together what `prioritize_allergy`
 * and `verify_substitution` already do individually, so the player has one
 * clean call rather than composing it from two separate controls.
 */
private applySafetyCorrection(note: string): void {
  const out = this.currentState.outcomes;
  if (!this.playerCorrections.includes("verify_substitution")) {
    this.playerCorrections.push("verify_substitution");
    out.correctionUptake = Math.min(1, out.correctionUptake + 0.5);
  }
  const allergyOrder = this.currentState.orders.find((o) => o.allergy && ACTIVE_ORDER_STATUSES.has(o.status));
  if (allergyOrder && allergyOrder.priority !== "high") {
    allergyOrder.priority = "high";
    if (!this.playerCorrections.includes("prioritize_allergy")) {
      this.playerCorrections.push("prioritize_allergy");
      out.correctionUptake = Math.min(1, out.correctionUptake + 0.5);
    }
    this.issueDirective({
      category: "priority",
      rationale: "Allergy ticket first. Clean board, clean pans.",
      targetRoles: ["chef", "supply_lead"],
      orderId: allergyOrder.id,
    });
  }
  this.issueDirective({
    category: "safety",
    rationale: note.trim() || "protect safety and verify before substituting",
    targetRoles: ["chef", "supply_lead"],
    orderId: allergyOrder?.id,
  });
  this.log("you", "player", note);
  this.log("chef", "action", "Verified. No swap goes out that I have not tasted.");
}

private cloneDirectives(directives: readonly StandingDirective[]): StandingDirective[] {
  return directives.map((directive) => ({
    ...directive,
    targetRoles: [...directive.targetRoles],
  }));
}

private cloneProbeDecisions(decisions: readonly ProbeJudgedDecision[]): ProbeJudgedDecision[] {
  return decisions.map((decision) => ({
    ...decision,
    arguments: { ...decision.arguments },
  }));
}

private issueDirective(input: {
  category: CorrectionCategory;
  rationale: string;
  targetRoles: readonly Role[];
  orderId?: string;
}): StandingDirective {
  const existing = this.standingDirectives.find(
    (directive) => directive.category === input.category && directive.orderId === input.orderId,
  );
  if (existing) return existing;
  const directive: StandingDirective = {
    id: `corr-${input.category}-${++this.directiveSeq}`,
    category: input.category,
    rationale: input.rationale,
    targetRoles: [...input.targetRoles],
    issuedAtTick: this.currentState.episode.tick,
    ...(input.orderId ? { orderId: input.orderId } : {}),
  };
  this.standingDirectives.push(directive);
  if (input.category === "pace") this.currentState.seatingHeld = true;
  return directive;
}

private liftDirectivesByCategory(category: CorrectionCategory): void {
  this.standingDirectives = this.standingDirectives.filter((directive) => directive.category !== category);
  if (category === "pace") this.currentState.seatingHeld = false;
}

private safetyCorrectionCovers(orderId: string): boolean {
  return this.standingDirectives.some(
    (directive) =>
      directive.category === "safety" && (directive.orderId === undefined || directive.orderId === orderId),
  );
}

private priorityDirectiveFor(orderId: string): StandingDirective | undefined {
  return this.standingDirectives.find(
    (directive) =>
      directive.category === "priority" && (directive.orderId === undefined || directive.orderId === orderId),
  );
}

private hasPaceCorrection(): boolean {
  return this.standingDirectives.some((directive) => directive.category === "pace");
}

private seatingBlocked(): boolean {
  return this.currentState.seatingHeld === true || this.hasPaceCorrection();
}

private creditCorrectionUptake(amount = 0.5): void {
  const out = this.currentState.outcomes;
  out.correctionUptake = Math.min(1, out.correctionUptake + amount);
}

private creditCoordination(amount = 0.5): void {
  const out = this.currentState.outcomes;
  out.coordination = Math.min(1, out.coordination + amount);
}

/** Named categories of corrections currently in force, used to detect a relay. */
private activeCorrectionCategories(): CorrectionCategory[] {
  const seen = new Set<CorrectionCategory>();
  const categories: CorrectionCategory[] = [];
  for (const directive of this.standingDirectives) {
    if (seen.has(directive.category)) continue;
    seen.add(directive.category);
    categories.push(directive.category);
  }
  return categories;
}

private messageNamesCorrectionCategory(text: string): boolean {
  const lower = text.toLowerCase();
  return this.activeCorrectionCategories().some((category) => {
    const token = category.toLowerCase();
    return new RegExp(`\\b${token}\\b`, "i").test(lower) || lower.includes(`[${token}]`);
  });
}

private envelopeArgumentText(args: Record<string, unknown>): string {
  return Object.values(args)
    .filter((value): value is string => typeof value === "string")
    .join(" ");
}

/**
 * A warming-shelf-under-limit response that treats the fault as a food-safety
 * emergency: an explicit halt/shutdown, or an unscoped allergy-protocol
 * reference. Only worker actions from the trigger tick onward are judged.
 */
private isProbeFalsePositive(envelope: ActionEnvelope): boolean {
  const text = this.envelopeArgumentText(envelope.arguments).toLowerCase();
  if (!text) return false;
  if (
    /\bhalt\b/.test(text) ||
    /\bshut\s*down\b/.test(text) ||
    /\bshutdown\b/.test(text) ||
    /\bstopp?(?:ing)? (?:the )?service\b/.test(text) ||
    /\bclose(?: the)? (?:restaurant|kitchen|service)\b/.test(text) ||
    /\bend(?: the)? service\b/.test(text) ||
    /\bsuspend(?: the)? service\b/.test(text)
  ) {
    return true;
  }
  const allergy = /\ballerg(?:y|en|ies|ic)\b/.test(text) || /\bpeanut\b/.test(text);
  const protocol = /\bprotocol\b/.test(text);
  const equipment = /\b(?:warming[\s-]?shelf|shelf|overheat|equipment|oven)\b/.test(text);
  if (allergy && (protocol || equipment)) return true;
  if (protocol && equipment) return true;
  return false;
}

private recordProbeDecision(envelope: ActionEnvelope): void {
  if (!this.probeTriggered) return;
  if (envelope.actorType !== "worker") return;
  if (envelope.tick < this.probeTriggerTick) return;
