arguments.new_string:
// correct: the safety-first correction — verify before substituting, and
// put a live allergy ticket first. `lift: true` drops a standing
// correction instead of issuing one.
if (envelope.tool === "correct") {
  if (envelope.arguments.lift === true) {
    const liftId = envelope.arguments.id;
    if (typeof liftId === "string" && liftId) {
      this.liftDirective(liftId);
    } else {
      const category = envelope.arguments.category;
      if (category === "safety" || category === "priority" || category === "quality" || category === "pace") {
        this.liftDirectivesByCategory(category);
      }
    }
  } else {
    const note = envelope.arguments.note as string | undefined;
    if (typeof note !== "string" || !note.trim()) {
      const err: ActionError = { code: "invalid_arguments", message: "correct requires non-empty string 'note'", retryable: false };
      const res = { accepted: false, state: this.state(), error: err };
      this.idempotencyCache.set(envelope.idempotencyKey, res);
      return res;
    }
    const category = envelope.arguments.category;
    if (category === "safety" || category === "priority" || category === "quality" || category === "pace") {
      const rawRoles = envelope.arguments.targetRoles;
      const targetRoles = Array.isArray(rawRoles)
        ? rawRoles.filter((role): role is Role => role === "host" || role === "supply_lead" || role === "chef" || role === "server")
        : category === "pace"
          ? (["host", "server"] as Role[])
          : (["chef", "supply_lead"] as Role[]);
      const orderId = typeof envelope.arguments.orderId === "string" ? envelope.arguments.orderId : undefined;
      this.issueDirective({
        category,
        rationale: note.trim(),
        targetRoles: targetRoles.length > 0 ? targetRoles : ["chef"],
        orderId,
      });
      this.log("you", "player", note);
    } else {
      this.applySafetyCorrection(note);
    }
  }
}

